def check_magic(x):
    n = len(x)
    for i in range(n):
        count = 0
        for j in range(n):
            if x[j] == i:
                count += 1
        if x[i] != count:
            return False
    return True

x = [7, 2, 1, 0, 0, 0, 0, 1, 0, 0, 0]
print(check_magic(x))
